"""Generate the bounded toolkit schema embedded in the .NET 4.8 adapter."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
def number(lo=-1e9, hi=1e9): return dict(type="number", minimum=lo, maximum=hi)
def integer(lo, hi): return dict(type="integer", minimum=lo, maximum=hi)
def text(): return dict(type="string", minLength=1, maxLength=256)
def choice(*values): return dict(type="string", enum=list(values))
def array(item, lo, hi): return dict(type="array", items=item, minItems=lo, maxItems=hi)
def obj(fields, required=()): return dict(type="object", properties=fields, required=list(required), additionalProperties=False)
vector = array(number(), 3, 3)
points = array(vector, 1, 256)
pid = dict(type="string", pattern="^[1-9][0-9]{0,18}$", maxLength=19)
definition_id = dict(type="string", pattern="^definition:[1-9][0-9]{0,18}$",maxLength=30)
ids = array(pid, 1, 128)
boolean = dict(type="boolean")
specs = {}
def tool(name, description, fields, required, read=False):
    common = dict(session_id=dict(type="string", format="uuid"), model_id=dict(type="string", format="uuid"))
    needed = ["session_id", "model_id"]
    if not read:
        common.update(command_id=dict(type="string", pattern="^[0-9a-fA-F-]{36}:[1-9][0-9]{0,9}$", maxLength=48), expected_context=array(pid,0,32), dry_run=boolean, ui_updates=dict(type="string",enum=['defer','normal'],default='defer',description='Native model operations only: defer suppresses intermediate UI/Outliner updates and requests one refresh after commit/abort. normal allows normal updates. No persistent freeze/tray visibility changes. Not applicable to camera/scenes.'))
        needed += ["command_id", "expected_context"]
    common.update(fields)
    specs["sketchup_"+name] = dict(description=description, read=read, schema=obj(common,needed+required))

tool("get_resources", "Read paged materials, tags, component definitions or camera scenes. Exact names/IDs; no permission required. Pages are live; restart after edits. No texture file contents.",
     dict(kind=choice("materials","tags","definitions","scenes"),offset=integer(0,1000000),limit=integer(1,25)), ["kind"], True)
tool("manage_resource", "Create/update/delete solid-color materials or tags, or purge unused definitions/materials/tags. Tag deletion preserves geometry and reassigns it to Layer0. Layer0 and active tag cannot be deleted. Purge is model-wide and requires confirm_model_wide=true. No texture file access.",
     dict(kind=choice("materials","tags","definitions"),action=choice("create","update","delete","purge_unused"),options=obj(dict(name=text(),new_name=text(),color_rgb=array(integer(0,255),3,3),alpha=number(0,1),visible=boolean,confirm_model_wide=boolean))),["kind","action","options"])
tool("component", "Convert groups to components, explode explicit groups/components, replace component definitions, create instances of an existing definition, or update definition name/description. Definition metadata affects all occurrences. Recursive definitions and glued targets are rejected; shared edits require explicit affect_all_instances=true.",
     dict(action=choice("convert","explode","replace","instantiate","metadata"),options=obj(dict(entity_ids=array(pid,1,25),definition_id=definition_id,name=text(),description=dict(type="string",maxLength=1024),origin_mm=vector,affect_all_instances=boolean))),["action","options"])
tool("create_geometry", "Create isolated geometry in a new group using model-axis mm: construction points, planar face, regular polygon, center/two-point(ends+signed bulge)/three-point arc, Bezier or freehand curve, closed oriented indexed polyhedron, convex planar polygon offset, revolution or Follow Me sweep. Precision is segments (3..128); no holes or self-intersecting profiles. See options required by each kind in docs/EXTENDED_TOOLKIT.md.",
     dict(kind=choice("points","face","polygon","arc_center","arc_two_point","arc_three_point","bezier","freehand","polyhedron","offset","revolve","sweep"),name=text(),options=obj(dict(points_mm=points,faces=array(array(integer(0,255),3,64),4,256),origin_mm=vector,plane=choice("XY","XZ","YZ"),radius_mm=number(1,1000000),sides=integer(3,128),segments=integer(3,128),start_degrees=number(-360,360),sweep_degrees=number(-360,360),bulge_mm=number(-1000000,1000000),distance_mm=number(-1000000,1000000),pivot_mm=vector,axis=vector,path_mm=array(vector,2,64)))),["kind","name","options"])
tool("edit_geometry", "Edit explicit raw children of one direct group/component. Unique definition required (use make_unique first). Add points/lines/faces, erase raw items, move construction points or edge endpoints, regenerate bounded faces, reverse faces, assign front/back materials, soften/smooth or unsoften edges, dissolve only coplanar internal edges. Edge deletion can remove adjacent faces. IDs/paths become stale after topology edits. No implicit edit-context changes.",
     dict(container_id=pid,affect_all_instances=boolean,action=choice("add_points","add_lines","add_face","erase","move_points","move_vertices","rebuild_faces","reverse_faces","properties","soften","unsoften","simplify"),options=obj(dict(entity_ids=ids,points_mm=points,delta_mm=vector,vertex_moves=array(obj(dict(edge_id=pid,endpoint=choice("start","end"),position_mm=vector),["edge_id","endpoint","position_mm"]),1,64),material=dict(type=["string","null"],minLength=1,maxLength=256),back_material=dict(type=["string","null"],minLength=1,maxLength=256),hidden=boolean,angle_degrees=number(0,180)))),["container_id","action","options"])
tool("mirror_entities", "Reflect up to25 explicit groups/components about a model-axis plane through pivot_mm. Preserves component sharing. One Undo operation; mirrored normals/handedness are inherent to reflection.",dict(entity_ids=array(pid,1,25),pivot_mm=vector,axis=choice("X","Y","Z")),["entity_ids","pivot_mm","axis"])
tool("configure_camera", "Set eye/target/up in model coordinates, perspective and FOV (degrees) or orthographic height (mm). Camera change has no model Undo and restores the previous camera on failure. Requires normal camera mode.",dict(eye_mm=vector,target_mm=vector,up=vector,perspective=boolean,fov_degrees=number(1,120),height_mm=number(1,1e9)),["eye_mm","target_mm","up","perspective"])
tool("scene", "Create/update/rename/delete camera-only scenes, or apply a saved scene's camera immediately without animation or applying its other flags. Existing scenes with other saved properties cannot be updated/deleted. Scene changes are not reliably model-Undoable in SketchUp2019; no automated destructive retry.",dict(action=choice("create","update","apply","delete"),name=text(),options=obj(dict(new_name=text(),description=dict(type="string",maxLength=1024)))),["action","name","options"])

tool("create_sliding_window", "Create an optimized parametric two-panel sliding window in one typed request and one operation/Undo. Model axes: X width, Z height, Y depth. Builds frame/rails, separate sliding sashes, 6mm-default glass, beads/seals and outer-stile flush pulls; applies existing materials and removes coplanar untextured seams internally without per-face RPCs. Four groups total. Explicit replace_entity_id atomically replaces one current direct group/component. open_sash selects left/right and open_fraction0..1; none requires0. Dimensions/profile/glass clearances validated together. Fixed4s cooperative budget; no arbitrary Ruby, file I/O or implicit edit-context changes. Native UI updates deferred until completion.",
     dict(name=text(),origin_mm=vector,width_mm=number(600,6000),height_mm=number(400,3600),depth_mm=number(80,300),frame_width_mm=number(30,100),sash_width_mm=number(20,80),glass_thickness_mm=number(3,12),overlap_mm=number(20,160),open_sash=choice("none","left","right"),open_fraction=number(0,1),materials=obj(dict(frame=text(),glass=text(),seal=text(),hardware=text()),["frame","glass","seal","hardware"]),replace_entity_id=pid),["name","origin_mm","width_mm","height_mm","depth_mm","materials"])

specs['sketchup_create_geometry']['description'] += ' Required options: points/face/freehand: points_mm; polygon: origin_mm,plane,radius_mm,sides; arc_center: origin_mm,plane,radius_mm,start_degrees,sweep_degrees; arc_two_point: points_mm=[start,end],plane,bulge_mm; arc_three_point: points_mm=[start,through,end]; bezier: points_mm(2..16 controls); polyhedron: points_mm,faces(index loops); offset: points_mm,distance_mm(positive outward); revolve: points_mm(closed profile),pivot_mm,axis,sweep_degrees; sweep: points_mm(closed profile),path_mm(start on profile plane, first segment normal). Optional segments for arcs/Bezier/revolve, default24. Mesh budget256 faces/2048 indexed corners.'
specs['sketchup_edit_geometry']['description'] = specs['sketchup_edit_geometry']['description'].replace('Unique definition required (use make_unique first).','Unique definition required, or explicit affect_all_instances=true for shared components; this edits their definition for all occurrences. Shared groups still require make_unique.') + ' Required options: add_points/add_lines/add_face: points_mm; move_vertices: vertex_moves(edge_id,endpoint=start/end,position_mm); others: entity_ids. move_points also delta_mm. properties: material/back_material(null clears),hidden. soften: optional angle_degrees default30, only two-face edges within angle. simplify: only untextured matching coplanar face pairs; verifies total area.'
specs['sketchup_component']['description'] += ' Required options: convert/explode: entity_ids; replace: entity_ids,definition_id; instantiate: definition_id,origin_mm; metadata: definition_id,affect_all_instances=true plus name/description. definition_id is a model-session-local definition:<entityID> returned by get_resources/get_entity_info, not a drawing persistent ID. Query fresh after model switching.'
# Explicit raw drawing; legacy creation tool defaults remain compatible.
import copy
geometry=copy.deepcopy(specs['sketchup_create_geometry']['schema']['properties'])
shape=geometry['options'];shape['properties']['size_mm']=array(number(1,1000000),2,2)
tool('draw_geometry','Draw model-axis geometry. Default grouping=auto draws points, lines, faces and native curves directly in the current edit context without temporary groups; closed solids are grouped. Direct drawing can merge/split existing geometry. Refresh IDs afterward. Choose group for isolation or none to require raw geometry. Native raw circular arcs require uniform edit scaling.',
     dict(kind=choice('rectangle','circle','polyline',*geometry['kind']['enum']),name=text(),grouping=dict(type='string',enum=['auto','none','group'],default='auto'),options=shape),['kind','options'])

tool('model_query','Read capabilities, bounded recursive physical metrics, ray hits, face point classification or paged custom attributes. No model changes. Metrics/classify require root edit context on2019; return model-axis mm/mm2/mm3. Repeated instances counted; overlapping solids not unioned.',
 dict(query=choice('capabilities','metrics','raycast','classify_point','attributes','display','face_mesh','uv'),options=obj(dict(instance_path=array(pid,1,32),points_mm=array(vector,1,64),front=boolean,origin_mm=vector,direction=vector,point_mm=vector,include_hidden=boolean,recursive=boolean,max_entities=integer(1,5000),dictionary=dict(type='string',minLength=1,maxLength=128),offset=integer(0,1000000),limit=integer(1,25)))),['query','options'],True)
tool('entity_attributes','Set or delete one custom attribute on a direct drawing entity. Shared edit ancestors and locked targets are rejected. value_json is a scalar/array JSON value; object metadata can be stored as a JSON string. Uses one Undo.',
 dict(action=choice('set','delete'),options=obj(dict(entity_id=pid,dictionary=dict(type='string',minLength=1,maxLength=128),key=dict(type='string',minLength=1,maxLength=128),value_json=dict(type='string',minLength=1,maxLength=8192)))),['action','options'])

tool('annotation','Create ungrouped guides, linear/radial dimensions, leader text or section planes at model root, model-axis mm. 3D text creates one group for safe placement without merging existing geometry; text uses XY plane. No implicit edit-mode changes.',
 dict(kind=choice('guide','linear_dimension','radial_dimension','text','text3d','section'),name=text(),options=obj(dict(point_mm=vector,direction=vector,start_mm=vector,end_mm=vector,offset_mm=vector,edge_id=pid,leader_mm=vector,text=dict(type='string',minLength=1,maxLength=2048),origin_mm=vector,height_mm=number(1,10000),font=text(),bold=boolean,italic=boolean,extrusion_mm=number(0,10000),normal=vector,active=boolean,symbol=dict(type='string',minLength=1,maxLength=3)))),['kind','options'])
tool('edit_annotation','At model root, erase explicit guides/dimensions/text/sections, change label text or edit a section plane position/normal, name, symbol or activation. Grouped 3D text uses ordinary group tools.',
 dict(action=choice('erase','section','text'),options=obj(dict(entity_ids=array(pid,1,25),entity_id=pid,text=dict(type='string',minLength=1,maxLength=2048),point_mm=vector,normal=vector,active=boolean,name=text(),symbol=dict(type='string',minLength=1,maxLength=3)))),['action','options'])
specs['sketchup_manage_resource']['schema']['properties']['options']['properties']['line_style']=dict(type=['string','null'],minLength=1,maxLength=256)
specs['sketchup_manage_resource']['description']+=' Tags accept line_style: exact name from model_query capabilities, or null for solid line (SketchUp2019+).'

tool('solid_operation','Native Boolean union/intersect/subtract/trim/outer_shell of two root solids, preserving both originals. Produces one isolated result. subtract/trim mean target minus tool. Pro required except outer_shell. Empty results fail and roll back. Face topology/material mapping changes; inspect result.',dict(operation=choice('union','intersect','subtract','trim','outer_shell'),target_id=pid,tool_id=pid,name=text()),['operation','target_id','tool_id'])
tool('intersect_faces','Insert raw intersection edges into one unique root group/component using another as cutter; no new groups, no automatic removal of unwanted faces. Direct faces/edges only;5000 entities each. Refresh paths after topology changes.',dict(target_id=pid,cutter_id=pid,include_hidden=boolean),['target_id','cutter_id'])
tool('face_texture','Position an existing textured material on a face, using1..4 model point(mm)/UV(unitless) pairs. Root context, unique unlocked ancestors required. Uses2019 position_material overload; no deprecated projection setter.',dict(instance_path=array(pid,1,32),material=text(),front=boolean,mapping=array(obj(dict(point_mm=vector,uv=array(number(-1e6,1e6),2,2)),['point_mm','uv']),1,4)),['instance_path','material','mapping'])
tool('component_behavior','Configure definition-wide opening, gluing, camera-facing and scale-handle behavior, or glue/unglue a direct component to a root face. Configure requires affect_all_instances=true. Opening is face cutting, not a wall-thickness Boolean.',dict(action=choice('configure','glue','unglue'),options=obj(dict(definition_id=definition_id,affect_all_instances=boolean,is2d=boolean,cuts_opening=boolean,always_face_camera=boolean,shadows_face_sun=boolean,snapto=integer(0,3),no_scale_mask=integer(0,127),entity_id=pid,face_id=pid))),['action','options'])

render={k:boolean for k in 'ModelTransparency MaterialTransparency DrawHidden DrawBackEdges DisplaySectionPlanes DisplaySectionCuts SectionCutFilled DisplayColorByLayer DisplayDims DisplayText DisplaySketchAxes DrawGround DrawHorizon'.split()}
render.update(RenderMode=integer(0,5),EdgeDisplayMode=integer(0,2),BackgroundColor=array(integer(0,255),3,3))
shadow={k:boolean for k in 'DisplayShadows DisplayOnGroundPlane DisplayOnAllFaces UseSunForAllShading EdgesCastShadows DaylightSavings'.split()}
shadow.update(Light=number(0,100),Dark=number(0,100),Latitude=number(-90,90),Longitude=number(-180,180),TZOffset=number(-14,14),NorthAngle=number(0,360),ShadowTime=dict(type='string',minLength=20,maxLength=25))
tool('configure_display','Configure bounded2019 rendering/style properties and shadow/geolocation settings at root. Query current values via model_query display. Explicit ISO8601 offset for ShadowTime. No reliable model Undo; restores prior values on failure. Excluded from library operations/batches.',dict(rendering=obj(render),shadows=obj(shadow)),[])
tool('export_view','Export current viewport to a NEW local PNG/JPEG path in an existing folder. No overwrite.64..4096 pixels. Returns size andSHA256. File output has no model Undo and is excluded from library operations/batches.',dict(path=dict(type='string',minLength=5,maxLength=1024),width=integer(64,4096),height=integer(64,4096),transparent=boolean),['path'])
tool('texture_resource','Load an existing local SKM, or create a new material from a PNG/JPEG texture with an explicit new name. Input <=64MiB, existing folder, root context. File reads are excluded from library operations/batches. Model material change uses one Undo.',dict(action=choice('create_texture','load_skm'),path=dict(type='string',minLength=5,maxLength=1024),name=text()),['action','path'])

specs['sketchup_edit_geometry']['schema']['required'].remove('container_id')
specs['sketchup_edit_geometry']['description']+=' Omit container_id to edit raw geometry directly in the current edit context, including model root, without grouping. Shared edit ancestors remain rejected. Current context budget2048 direct entities.'

target=ROOT/'shared/ToolkitSchemas.json'
target.write_text(json.dumps(specs,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
source=json.dumps(specs,ensure_ascii=True,separators=(',',':')).replace('"','""')
template=(ROOT/'scripts/ToolkitCatalog.template').read_text(encoding='utf-8')
(ROOT/'shared/ToolkitCatalog.cs').write_text(template.replace('SCHEMAS_JSON',source),encoding='utf-8')
